import React, { useEffect, useState } from 'react'
import AttendanceTable from './AttendanceTable'
import Filters from './Filters'

const API = 'http://localhost:5000/api/attendance'
const COLUMNS = ['SN#', 'Name', 'Roll No.', 'Course', 'Year', 'Branch', 'Date']

/* Reusable class strings */
const btnBase =
  'inline-flex h-10 items-center gap-2 rounded-lg px-4 text-sm font-semibold transition-colors ' +
  'focus:outline-none focus-visible:ring-4 focus-visible:ring-indigo-500/30'
const btnPrimary =
  btnBase +
  ' bg-indigo-600 text-white hover:bg-indigo-700 dark:bg-indigo-400 dark:text-slate-900 dark:hover:bg-indigo-300'
const btnGhost =
  btnBase +
  ' border border-slate-200 text-slate-600 hover:bg-slate-100 hover:text-slate-900 ' +
  'dark:border-slate-700 dark:text-slate-400 dark:hover:bg-slate-800 dark:hover:text-slate-100'

const Attendancelist = () => {
  const [attendancelist, setMyAlist] = useState([])
  const [dates, setMydates] = useState('')
  const [datas, setMydatas] = useState(null)
  const [showFilters, setShowFilters] = useState(false)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  // One effect picks the endpoint. A date and a course filter are mutually exclusive:
  // whichever the user picked last wins.
  useEffect(() => {
    const controller = new AbortController()

    let url = `${API}/attendancelist`
    if (dates) {
      url = `${API}/datelist/${dates}T00:00:00.000Z`
    } else if (datas) {
      url = `${API}/filterattendance/${datas.course}/${datas.year}/${datas.branch}`
    }

    const load = async () => {
      setLoading(true)
      setError(null)
      try {
        const response = await fetch(url, {
          method: 'GET',
          headers: { 'Content-Type': 'application/json' },
          signal: controller.signal,
        })
        const json = await response.json()
        setMyAlist(Array.isArray(json) ? json : [])
      } catch (err) {
        if (err.name !== 'AbortError') {
          setMyAlist([])
          setError('Could not load attendance. Check that the server is running and try again.')
        }
        return
      }
      setLoading(false)
    }

    load()
    return () => controller.abort()
  }, [dates, datas])

  const handelchange = (e) => {
    setMydates(e.target.value)
    setMydatas(null)
  }

  const handelsubmit = (data) => {
    setMydatas(data)
    setMydates('')
  }

  const clearAll = () => {
    setMydates('')
    setMydatas(null)
  }

  const hasActiveFilter = Boolean(dates || datas)

  const emptyMessage = dates
    ? 'No attendance was recorded for this date.'
    : datas
    ? 'No records match these filters.'
    : 'No attendance records yet.'

  const chipClass =
    'rounded-full bg-indigo-100 px-2.5 py-0.5 text-xs font-semibold text-indigo-700 ' +
    'dark:bg-indigo-500/20 dark:text-indigo-300'

  return (
    <div className="px-4 pb-12 pt-6 text-slate-800 dark:text-slate-100">
      <div className="mx-auto max-w-6xl">
        {/* Toolbar */}
        <div className="mb-4 flex flex-wrap items-center justify-between gap-4">
          <div className="flex flex-wrap items-baseline gap-3">
            <h2 className="text-2xl font-bold tracking-tight">Attendance records</h2>
            <span className="text-sm text-slate-500 dark:text-slate-400" aria-live="polite">
              {loading
                ? 'Loading…'
                : `${attendancelist.length} ${attendancelist.length === 1 ? 'record' : 'records'}`}
            </span>
          </div>

          <div className="flex w-full flex-wrap items-center gap-2 sm:w-auto">
            <label
              htmlFor="date"
              className="flex h-10 w-full items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 text-slate-500
                         focus-within:border-indigo-500 focus-within:ring-4 focus-within:ring-indigo-500/20
                         dark:border-slate-700 dark:bg-slate-900 dark:text-slate-400 sm:w-auto"
            >
              <i className="fa-regular fa-calendar" aria-hidden="true"></i>
              <input
                type="date"
                name="date"
                id="date"
                value={dates}
                onChange={handelchange}
                aria-label="Filter by date"
                className="bg-transparent text-sm text-slate-800 outline-none [color-scheme:light] dark:text-slate-100 dark:[color-scheme:dark]"
              />
            </label>

            <button
              type="button"
              className={btnPrimary}
              onClick={() => setShowFilters((s) => !s)}
              aria-expanded={showFilters}
              aria-controls="dropdowncontents"
            >
              <i className="fa-solid fa-sliders" aria-hidden="true"></i>
              Filter
              <i
                className={`fa-solid fa-chevron-down text-[0.7rem] transition-transform duration-200 ${
                  showFilters ? 'rotate-180' : ''
                }`}
                aria-hidden="true"
              ></i>
            </button>

            {hasActiveFilter && (
              <button type="button" className={btnGhost} onClick={clearAll}>
                <i className="fa-solid fa-xmark" aria-hidden="true"></i>
                Clear
              </button>
            )}
          </div>
        </div>

        {/* Active filter chips */}
        {hasActiveFilter && (
          <div className="mb-4 flex flex-wrap gap-1.5">
            {dates && <span className={chipClass}>Date: {dates}</span>}
            {datas?.course && <span className={chipClass}>Course: {datas.course}</span>}
            {datas?.year && <span className={chipClass}>Year: {datas.year}</span>}
            {datas?.branch && <span className={chipClass}>Branch: {datas.branch}</span>}
          </div>
        )}

        {/* Filters panel (animated open/close) */}
        <div
          id="dropdowncontents"
          className={`grid transition-[grid-template-rows] duration-300 ease-out motion-reduce:transition-none ${
            showFilters ? 'grid-rows-[1fr]' : 'grid-rows-[0fr]'
          }`}
        >
          <div className="min-h-0 overflow-hidden">
            <div
              className="mb-4 rounded-2xl border border-slate-200 bg-white p-5 shadow-sm
                         dark:border-slate-700 dark:bg-slate-900
                         [&_label]:text-sm [&_label]:font-semibold [&_label]:text-slate-500 dark:[&_label]:text-slate-400
                         [&_.form-control]:border-slate-200 [&_.form-control]:bg-slate-50 [&_.form-control]:text-slate-800
                         dark:[&_.form-control]:border-slate-700 dark:[&_.form-control]:bg-slate-800 dark:[&_.form-control]:text-slate-100
                         [&_.form-select]:border-slate-200 [&_.form-select]:bg-slate-50 [&_.form-select]:text-slate-800
                         dark:[&_.form-select]:border-slate-700 dark:[&_.form-select]:bg-slate-800 dark:[&_.form-select]:text-slate-100"
            >
              <Filters handelsubmit={handelsubmit} />
            </div>
          </div>
        </div>

        {/* Table card */}
        <div className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-slate-700 dark:bg-slate-900">
          <div className="max-h-[70vh] overflow-auto">
            <table className="w-full border-collapse text-left text-[0.925rem]">
              <thead>
                <tr>
                  {COLUMNS.map((col) => (
                    <th
                      scope="col"
                      key={col}
                      className="sticky top-0 z-10 whitespace-nowrap border-b border-slate-200 bg-slate-100 px-4 py-3.5
                                 text-xs font-bold tracking-wide text-slate-500
                                 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-400"
                    >
                      {col}
                    </th>
                  ))}
                </tr>
              </thead>

              <tbody>
                {loading &&
                  [0, 1, 2, 3, 4].map((i) => (
                    <tr key={`sk-${i}`} aria-hidden="true">
                      <td colSpan={COLUMNS.length} className="px-4 py-3">
                        <div className="h-4 animate-pulse rounded bg-slate-200 dark:bg-slate-700" />
                      </td>
                    </tr>
                  ))}

                {!loading &&
                  attendancelist.map((attend, index) => (
                    <tr
                      key={index}
                      className="border-b border-slate-100 transition-colors last:border-0
                                 even:bg-slate-50/70 hover:bg-indigo-50
                                 dark:border-slate-800 dark:even:bg-white/[0.03] dark:hover:bg-indigo-500/10
                                 [&>*]:whitespace-nowrap [&>*]:px-4 [&>*]:py-3 [&>*]:align-middle
                                 [&>*:first-child]:w-16 [&>*:first-child]:text-slate-400
                                 [&>*:nth-child(2)]:font-semibold
                                 [&>*:nth-child(3)]:tabular-nums
                                 [&>*:last-child]:tabular-nums [&>*:last-child]:text-slate-500 dark:[&>*:last-child]:text-slate-400"
                    >
                      <AttendanceTable attend={attend} index={index} />
                    </tr>
                  ))}

                {!loading && attendancelist.length === 0 && (
                  <tr>
                    <td colSpan={COLUMNS.length}>
                      <div className="flex flex-col items-center gap-2 px-4 py-14 text-center">
                        <i
                          className={`text-3xl ${
                            error
                              ? 'fa-solid fa-triangle-exclamation text-red-600 dark:text-red-400'
                              : 'fa-regular fa-calendar-xmark text-indigo-600 dark:text-indigo-400'
                          }`}
                          aria-hidden="true"
                        ></i>
                        <p className="max-w-md text-slate-500 dark:text-slate-400">
                          {error || emptyMessage}
                        </p>
                        {hasActiveFilter && !error && (
                          <button type="button" className={btnGhost} onClick={clearAll}>
                            Show all records
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  )
}

export default Attendancelist
